INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-san-ildefonso', 'Catedral de San Ildefonso', 'San Ildefonso', 'Calle 60 s/n, entre 61 y 63', 'Centro Histórico', 20.9671302, -89.6225405, '+52 999 924 1001', 'hola@sanildefonso.mx', 'Pbro. David Ceballos', '1561', 'El corazón espiritual del Centro Histórico. Una comunidad que ora, celebra y camina junta desde hace más de cuatro siglos.', 'Ser una casa abierta donde cada persona encuentre acogida, propósito y un lugar para servir.', NULL, '#8A5A2B', '#2A1E13', '#D8B36A', '#F3E8D5', '#EFE0C8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/bf/Catedral_de_San_Ildefonso%2C_M%C3%A9rida%2C_Yucat%C3%A1n%2C_fachada_principal.jpg/1280px-Catedral_de_San_Ildefonso%2C_M%C3%A9rida%2C_Yucat%C3%A1n%2C_fachada_principal.jpg', 'Fachada principal de la Catedral de San Ildefonso en el Centro de Mérida', 'Gideonximi', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Catedral_de_San_Ildefonso,_M%C3%A9rida,_Yucat%C3%A1n,_fachada_principal.jpg', NULL, 'La construcción comenzó en 1562 y el templo se terminó el 1 de enero de 1597; su cierre formal fue en 1598.', 'Basílica de lenguaje renacentista-manierista, integrada con el Sagrario Metropolitano y otros espacios históricos.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-ildefonso', 'Domingo', '08:00', 'Misa de aurora');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-ildefonso', 'Domingo', '12:00', 'Misa de comunidad');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-ildefonso', 'Miércoles', '19:00', 'Oración y alabanza');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-ildefonso', '1562', 'Inicia la construcción de la Catedral.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-ildefonso', '1597–1598', 'Se concluye el templo y se formaliza su terminación.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-ildefonso', '1935', 'Es declarada Monumento Histórico.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-san-cristobal', 'Templo de San Cristóbal', 'San Cristóbal', 'Calle 50 x 69, Barrio de San Cristóbal', 'San Cristóbal', 20.9611506, -89.6174098, '+52 999 925 4024', 'contacto@sancristobal.mx', 'Pbro. Jorge Medina', '1542', 'Una iglesia de barrio con vocación de servicio. Aquí las puertas se abren temprano y la mesa siempre tiene un lugar más.', 'Vivir el evangelio en lo cotidiano: acompañar familias, formar discípulos y servir a la ciudad.', NULL, '#A34E36', '#2B1A15', '#E0A96D', '#F7E5DB', '#F1D5C7', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/2/22/Fachada_principal_de_la_Parroquia_de_San_Crist%C3%B3bal.jpg/960px-Fachada_principal_de_la_Parroquia_de_San_Crist%C3%B3bal.jpg', 'Fachada principal del Templo de San Cristóbal en Mérida', 'Lilitharq', 'CC BY 4.0', 'https://commons.wikimedia.org/wiki/File:Fachada_principal_de_la_Parroquia_de_San_Crist%C3%B3bal.jpg', NULL, 'El templo actual corresponde al último tercio del siglo XVIII y forma parte del histórico barrio de San Cristóbal.', 'Barroco sobrio: su portada central se distingue por la gran concha que la corona, un rasgo singular en Mérida.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-cristobal', 'Domingo', '09:00', 'Culto de celebración');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-cristobal', 'Domingo', '18:00', 'Culto vespertino');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-cristobal', 'Jueves', '19:30', 'Estudio bíblico');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-cristobal', '1542', 'Se forma el barrio para población indígena aliada de la conquista.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-cristobal', 'Siglo XVIII', 'Se construye la parroquia actual.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-cristobal', '1796', 'La iglesia queda registrada entre los monumentos históricos de Mérida.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-santa-lucia', 'Iglesia de Santa Lucía', 'Santa Lucía', 'Calle 60 #502, esquina con 55', 'Centro Histórico', 20.9710283, -89.6219182, '+52 999 923 3170', 'bienvenida@santalucia.mx', 'Pbro. Andrés Pech', '1575', 'Frente al parque más querido de Mérida, una comunidad pequeña de corazón grande que hace de la música una forma de oración.', 'Cultivar la belleza, la escucha y el servicio como caminos para encontrarnos con Dios y con la ciudad.', NULL, '#64714A', '#1F261B', '#C7B576', '#EDECDC', '#E2E2CE', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b8/IGLESIA_DE_SANTA_LUC%C3%8DA_EN_M%C3%89RIDA_FACHADA.jpg/960px-IGLESIA_DE_SANTA_LUC%C3%8DA_EN_M%C3%89RIDA_FACHADA.jpg', 'Fachada de cantera de la Iglesia de Santa Lucía, en el Centro de Mérida', 'Jami.rc.08', 'CC0', 'https://commons.wikimedia.org/wiki/File:IGLESIA_DE_SANTA_LUC%C3%8DA_EN_M%C3%89RIDA_FACHADA.jpg', '50% 20%', 'Su construcción comenzó a finales del siglo XVI y concluyó en 1620. El atrio fue cementerio de la ciudad hasta 1821.', 'Templo colonial de fachada sobria, entrada rectangular de cantera, vitral y espadaña; conserva un mural de Ermilo Torre Gamboa.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santa-lucia', 'Domingo', '07:30', 'Misa temprana');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santa-lucia', 'Domingo', '11:00', 'Misa de familia');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santa-lucia', 'Viernes', '19:00', 'Noche de música y oración');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santa-lucia', 'Finales del siglo XVI', 'Comienza la construcción del templo.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santa-lucia', '1620', 'Se concluye la iglesia.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santa-lucia', '1950', 'Ermilo Torre Gamboa pinta el mural del martirio de Santa Lucía.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-fatima', 'Parroquia de Nuestra Señora de Fátima', 'Fátima', 'Calle 20 #204, entre 23 y 25', 'García Ginerés', 20.9865101, -89.6326413, '+52 999 925 3554', 'secretaria@fatima.mx', 'Pbro. Ricardo Alcocer', '1956', 'En el corazón de García Ginerés, una parroquia mariana que reúne a las familias alrededor de la Virgen de Fátima y acompaña los ciclos de la vida del barrio.', 'Formar una comunidad cercana, misericordiosa y comprometida con la formación de las nuevas generaciones.', NULL, '#7B3C48', '#261419', '#D6A96B', '#F4E3E5', '#EFD6D9', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/3/32/Parroquia_de_Nuestra_Se%C3%B1ora_de_F%C3%A1tima_-_2015-02-25_M%C3%A9rida%2C_Yucat%C3%A1n.jpg/1280px-Parroquia_de_Nuestra_Se%C3%B1ora_de_F%C3%A1tima_-_2015-02-25_M%C3%A9rida%2C_Yucat%C3%A1n.jpg', 'Fachada de la Parroquia de Nuestra Señora de Fátima en García Ginerés', 'Cecilia Ortiz', 'CC BY 2.0', 'https://commons.wikimedia.org/wiki/File:Parroquia_de_Nuestra_Se%C3%B1ora_de_F%C3%A1tima_-_2015-02-25_M%C3%A9rida,_Yucat%C3%A1n.jpg', NULL, 'El templo actual se levantó entre 1952 y 1956 en la colonia García Ginerés, junto al Parque de las Américas.', 'Arquitectura religiosa de mediados del siglo XX, vinculada al desarrollo urbano de García Ginerés; destaca por sus vitrales.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-fatima', 'Sábado', '18:00', 'Misa de anticipación');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-fatima', 'Domingo', '08:30', 'Misa de comunidad');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-fatima', 'Domingo', '12:30', 'Misa de jóvenes');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-fatima', '1901', 'Joaquín García Ginerés impulsa la colonia que llevaría su nombre.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-fatima', '1952–1956', 'Ulises González Torres y Álvaro Ponce Peón construyen el templo actual.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-fatima', '13 de mayo', 'La comunidad celebra anualmente a Nuestra Señora de Fátima.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-itzimna', 'Parroquia de Nuestra Señora del Perpetuo Socorro', 'Itzimná', 'Calle 20 x 19, Barrio de Itzimná', 'Itzimná', 20.9917578, -89.6105779, '+52 999 926 2231', 'hola@perpetuosocorro.mx', 'Pbro. Fernando Uc', '1572', 'La iglesia histórica de Itzimná, una comunidad que crece al ritmo de sus niños, jóvenes y vecinos y que mantiene viva la memoria del barrio.', 'Ser semilla de esperanza en Itzimná, formando comunidades pequeñas que se cuidan y sirven entre sí.', NULL, '#44557C', '#191D2A', '#D3B578', '#E5E8F1', '#D8DCEA', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/9/91/Parroquia_de_Nuestra_Se%C3%B1ora_del_Perpetuo_Socorro.JPG/1280px-Parroquia_de_Nuestra_Se%C3%B1ora_del_Perpetuo_Socorro.JPG', 'Fachada roja de la Parroquia de Nuestra Señora del Perpetuo Socorro en Itzimná, Mérida', 'Aubolio', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Parroquia_de_Nuestra_Se%C3%B1ora_del_Perpetuo_Socorro.JPG', NULL, 'En el sitio hubo una capilla de 1572; el templo conservado se edificó en 1710 y su pila bautismal recuerda la etapa temprana.', 'Fachada sobria con espadaña de tres vanos, portada de medio punto y ventana coral; conserva una imagen traída de París a inicios del siglo XX.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-itzimna', 'Domingo', '09:30', 'Misa de familia');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-itzimna', 'Domingo', '19:00', 'Misa de jóvenes');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-itzimna', 'Martes', '19:00', 'Grupo de oración');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-itzimna', '1572', 'Se levanta una primera capilla en el antiguo Itzimná.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-itzimna', '1710', 'Se edifica el templo que permanece hoy.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-itzimna', '1944', 'Se dedica a Nuestra Señora del Perpetuo Socorro.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-santa-ana', 'Templo de Santa Ana', 'Santa Ana', 'Calle 45, esquina con 60', 'Centro · Parque de Santa Ana', 20.9764989, -89.6209715, '+52 999 928 1240', 'hola@santaanamerida.mx', 'Pbro. Manuel Solís', '1733', 'Una comunidad de artesanos, familias y vecinos que se reúne bajo las torres de Santa Ana, a unos pasos del Paseo de Montejo y del bullicio sereno del parque.', 'Ser una comunidad abierta y cercana, donde la fe se vuelve servicio y la ciudad encuentra un lugar para descansar.', NULL, '#C0653F', '#261A14', '#E9C98E', '#F7E7DC', '#F0D7C8', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/c/cf/Fachada_principal_Templo.jpg/1280px-Fachada_principal_Templo.jpg', 'Fachada principal del Templo de Santa Ana, en Mérida', 'Veronicat01', 'CC BY-SA 3.0', 'https://commons.wikimedia.org/wiki/File:Fachada_principal_Templo.jpg', NULL, 'El templo se levantó entre 1726 y 1733 por orden del gobernador Antonio de Figueroa y Silva, sobre un basamento maya y una antigua capilla abierta.', 'Fachada de dos torres, portada de cantera y un nicho central con la imagen de Santa Ana. El conjunto se asoma al parque y al antiguo mercado del barrio.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santa-ana', 'Domingo', '08:00', 'Misa de aurora');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santa-ana', 'Domingo', '11:00', 'Misa de comunidad');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santa-ana', 'Miércoles', '19:00', 'Oración y alabanza');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santa-ana', '1726', 'El gobernador Antonio de Figueroa y Silva ordena construir el templo y el paseo de Santa Ana.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santa-ana', '1733', 'Se concluye el conjunto de templo, atrio y alameda.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santa-ana', '1867', 'El parque de Santa Ana es escenario de una batalla decisiva para la República en Yucatán.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-santiago-apostol', 'Iglesia de Santiago Apóstol', 'Santiago', 'Calle 59 x 72, Barrio de Santiago', 'Santiago', 20.9700911, -89.6294126, '+52 999 928 5670', 'contacto@santiagoapostol.mx', 'Pbro. Gabriel Uc', '1637', 'La iglesia del barrio más antiguo de Mérida, donde la memoria maya, la vida de la ciudad y la devoción a Santiago se encuentran desde el siglo XVI.', 'Caminar con el barrio, cuidar su memoria y hacer del templo una casa de encuentro para todas las generaciones.', NULL, '#3E6173', '#16232A', '#D8A85E', '#E7EFF2', '#D8E4E9', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/7/7d/Iglesia_de_Santiago_Ap%C3%B3stol%2C_M%C3%A9rida%2C_Yucat%C3%A1n_%2801%29.jpg/1280px-Iglesia_de_Santiago_Ap%C3%B3stol%2C_M%C3%A9rida%2C_Yucat%C3%A1n_%2801%29.jpg', 'Fachada blanca de la Iglesia de Santiago Apóstol, en Mérida', 'Inri', 'CC0', 'https://commons.wikimedia.org/wiki/File:Iglesia_de_Santiago_Ap%C3%B3stol,_M%C3%A9rida,_Yucat%C3%A1n_(01).jpg', NULL, 'El barrio se organizó desde 1542 como pueblo de indios. La iglesia se concluyó en 1637 y su capilla lateral conserva la memoria de la primera misa celebrada en una capilla de la ciudad.', 'Fachada barroca de espadaña escalonada, tres campanas y portada de cantera. El conjunto conserva la capilla de la Tercera Orden y un atrio de escala barrial.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santiago-apostol', 'Domingo', '07:30', 'Misa de aurora');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santiago-apostol', 'Domingo', '12:00', 'Misa de comunidad');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-santiago-apostol', 'Jueves', '19:00', 'Adoración y oración');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santiago-apostol', '1542', 'El barrio de Santiago queda integrado como pueblo de indios a la naciente Mérida.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santiago-apostol', '1637', 'Se concluye la iglesia.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-santiago-apostol', '1925', 'Se reconstruye casi por completo la capilla lateral.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-mejorada', 'Templo de Nuestra Señora del Tránsito de Mejorada', 'La Mejorada', 'Calle 50, entre 59 y 57', 'Centro · Parque de La Mejorada', 20.9677044, -89.615909, '+52 999 924 7890', 'secretaria@mejorada.mx', 'Pbro. Francisco Escalante', '1640', 'Un templo franciscano que hoy comparte su historia con la Facultad de Arquitectura y con el parque donde se instaló el primer riel de Yucatán.', 'Honrar una historia de más de cuatro siglos y seguir siendo una casa de oración, arte y encuentro para el centro de Mérida.', NULL, '#6C7059', '#20231B', '#CBB37B', '#ECEDE1', '#E0E2D1', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/5/55/Fachada_del_Templo_de_la_Mejorada%2C_M%C3%A9rida%2C_Yucat%C3%A1n.jpg/1280px-Fachada_del_Templo_de_la_Mejorada%2C_M%C3%A9rida%2C_Yucat%C3%A1n.jpg', 'Fachada de cantera del Templo de la Mejorada, en Mérida', 'Luis Alvaz', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Fachada_del_Templo_de_la_Mejorada,_M%C3%A9rida,_Yucat%C3%A1n.jpg', NULL, 'La construcción comenzó en 1621 con recursos de Diego Montalvo de García y fue concluida por los franciscanos en 1640. El convento anexo, edificado entre 1688 y 1694, hoy alberga la Facultad de Arquitectura de la UADY.', 'Templo colonial de una nave con fachada de cantera, dos espadañas y un claustro conventual. Frente al parque se instaló el primer riel de la península en 1870.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-mejorada', 'Domingo', '09:00', 'Misa de familia');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-mejorada', 'Domingo', '18:00', 'Misa vespertina');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-mejorada', 'Viernes', '19:00', 'Oración ante el Santísimo');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-mejorada', '1621', 'Comienza la construcción del templo con recursos de Diego Montalvo de García.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-mejorada', '1640', 'Los franciscanos concluyen la obra.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-mejorada', '1688–1694', 'Se construye el convento anexo.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-mejorada', '1870', 'Se instala en el parque el primer riel de ferrocarril de Yucatán.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('iglesia-san-sebastian', 'Parroquia de San Sebastián', 'San Sebastián', 'Calle 75 x 69, Barrio de San Sebastián', 'San Sebastián', 20.9588896, -89.6320711, '+52 999 923 4560', 'parroquia@sansebastian.mx', 'Pbro. Jorge Medina', '1796', 'Una parroquia de barrio conocida por sus fiestas de agosto, sus gremios y su vocación de acogida. Aquí la comunidad se reconoce y se celebra.', 'Ser una parroquia de puertas abiertas, donde las familias del barrio encuentren acompañamiento, fiesta y servicio.', NULL, '#8F4F5C', '#29181D', '#DDB66F', '#F4E5E5', '#ECD4D4', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/f8/San_Sebasti%C3%A1n%2C_M%C3%A9rida%2C_Yucat%C3%A1n.jpg/1280px-San_Sebasti%C3%A1n%2C_M%C3%A9rida%2C_Yucat%C3%A1n.jpg', 'Parroquia de San Sebastián iluminada al anochecer, en Mérida', 'Mario Morales Rubí', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:San_Sebasti%C3%A1n,_M%C3%A9rida,_Yucat%C3%A1n.jpg', NULL, 'La primera ermita del barrio se levantó a mediados del siglo XVI. El templo actual fue concluido en 1796 por Juan Esteban Quijana y un grupo de vecinos, y en 1889 fue elevado a parroquia.', 'Fachada de cantera con espadaña central, dos torres laterales y un atrio que conserva la escala de los antiguos barrios de Mérida.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-sebastian', 'Sábado', '18:00', 'Misa de anticipación');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-sebastian', 'Domingo', '08:00', 'Misa de aurora');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('iglesia-san-sebastian', 'Domingo', '11:30', 'Misa de comunidad');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-sebastian', 'Siglo XVI', 'Se construye una humilde ermita en el barrio.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-sebastian', '1796', 'Se concluye el templo actual.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-sebastian', '1889', 'El obispo Crescencio Carrillo y Ancona la eleva a parroquia.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('iglesia-san-sebastian', 'Agosto', 'La comunidad celebra sus fiestas patronales con gremios y vaquerías.');
INSERT INTO churches (id, name, short_name, address, colonia, lat, lng, phone, email, pastor, founded, description, mission, logo, theme_primary, theme_deep, theme_accent, theme_soft, theme_tint, photo_src, photo_alt, photo_credit, photo_license, photo_source, photo_position, history_summary, history_architecture) VALUES ('ermita-santa-isabel', 'Ermita de Santa Isabel', 'Santa Isabel', 'Calle 66 sur x 77, Barrio de San Sebastián', 'San Sebastián', 20.9567861, -89.629633, '+52 999 923 8901', 'ermita@santaisabel.mx', 'Pbro. Andrés Pech', 'Siglo XVII', 'La pequeña ermita amarilla que marcaba el inicio del Camino Real a Campeche, hoy un refugio de silencio y memoria en el sur del centro.', 'Guardar la memoria del camino y ofrecer a quien pasa un lugar de pausa, oración y hospitalidad.', NULL, '#B07F2E', '#2A2112', '#EBD08B', '#F6EDD9', '#EFE0C2', 'https://thumb.wikimedia.org/wikipedia/commons/thumb/f/fe/Ermita_de_Santa_Isabel_1.jpg/1280px-Ermita_de_Santa_Isabel_1.jpg', 'Fachada amarilla de la Ermita de Santa Isabel, en Mérida', 'Muñoz LC', 'CC BY-SA 4.0', 'https://commons.wikimedia.org/wiki/File:Ermita_de_Santa_Isabel_1.jpg', NULL, 'La ermita fue construida por Gaspar González de Ledezma en el siglo XVII, al inicio del Camino Real a Campeche. Sobre su puerta mayor se lee la inscripción de 1748.', 'Pequeña capilla de fachada amarilla con espadaña de tres vanos, atrio escalonado y muros de cantera. Fue conocida como Ermita de Nuestra Señora del Buen Viaje.');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('ermita-santa-isabel', 'Sábado', '17:30', 'Rosario en la ermita');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('ermita-santa-isabel', 'Domingo', '08:00', 'Misa de la ermita');
INSERT INTO church_schedules (church_id, day, time, label) VALUES ('ermita-santa-isabel', 'Jueves', '18:30', 'Oración por los viajeros');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('ermita-santa-isabel', 'Siglo XVII', 'Gaspar González de Ledezma manda construir la ermita.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('ermita-santa-isabel', '1748', 'Se graba la inscripción de la puerta mayor.');
INSERT INTO church_history_timeline (church_id, year, event) VALUES ('ermita-santa-isabel', '1790', 'El camino real a Campeche pasa frente a la ermita y le da nueva vida.');
