INSERT INTO announcements (id, church_id, title, body, category, published_at, pinned, author_id) VALUES ('n_0_0', 'iglesia-san-ildefonso', 'Retiro de comunidad: inscripciones abiertas', 'Del viernes 21 al domingo 23 viviremos nuestro retiro anual en Celestún. Cupo limitado a 40 personas. Puedes registrarte con tu coordinador de ministerio o en la secretaría después de cada celebración.', 'evento', '2026-11-04', 1, 'u_pastor');
INSERT INTO announcements (id, church_id, title, body, category, published_at, pinned, author_id) VALUES ('n_0_1', 'iglesia-san-ildefonso', 'Nuevo horario de secretaría', 'A partir de este mes la secretaría atenderá de lunes a viernes de 9:00 a 14:00 y de 16:00 a 19:00. Para trámites de documentos, te recomendamos escribir antes al correo de la iglesia.', 'general', '2026-10-31', 0, 'u_pastor');
INSERT INTO announcements (id, church_id, title, body, category, published_at, pinned, author_id) VALUES ('n_0_2', 'iglesia-san-ildefonso', 'Colecta para las familias afectadas', 'Durante todo el mes estaremos recibiendo despensas y artículos de primera necesidad para las familias del sur de la ciudad. Puedes dejar tu aportación en el atrio o sumarte al servicio comunitario del próximo sábado.', 'servicio', '2026-10-26', 0, 'u_pastor');
